function admin_header(string $title): void {require __DIR__.'/../includes/header.php';echo '<div class="admin-layout"><aside><h2>จัดการร้านค้า</h2>';foreach([''=>'ภาพรวม','products.php'=>'สินค้า','categories.php'=>'หมวดหมู่','orders.php'=>'คำสั่งซื้อ','payment_settings.php'=>'ตั้งค่าชำระเงิน','shipping.php'=>'บริการขนส่ง','shipping_agreements.php'=>'แผนข้อตกลงขนส่ง','inventory.php'=>'สต๊อก / สี / ไซซ์','product_options.php'=>'ภาษา / ภาษีสินค้า','taxes.php'=>'ตั้งค่าภาษี','promotions.php'=>'โปรโมชั่น/คูปอง','users.php'=>'สมาชิก','reports.php'=>'รายงาน','analytics.php'=>'สถิติการเข้าชม','privacy_requests.php'=>'คำขอข้อมูล','contact.php'=>'จัดการข้อมูลติดต่อ','contact_messages.php'=>'ข้อความลูกค้า'] as $path=>$label)echo '<a href="'.url('admin/'.$path).'">'.e(t($label)).'</a>';echo '</aside><div class="admin-content"><h1>'.e(t($title)).'</h1>';}
function admin_footer(): void {echo '</div></div>';require __DIR__.'/../includes/footer.php';}
